def car_fleet(target, position, speed):
    fleets, slowest = 0, 0.0           # arrival time of the fleet just ahead
    for p, s in sorted(zip(position, speed), reverse=True):
        time = (target - p) / s
        if time > slowest:
            fleets += 1                # can't catch up: a new fleet
            slowest = time
    return fleets

