def daily_temperatures(temps):
    n = len(temps)
    res = [0] * n
    for i in range(n - 2, -1, -1):     # right to left: res[j] is known for j > i
        j = i + 1
        while temps[j] <= temps[i] and res[j]:
            j += res[j]                # jump straight to j's next warmer day
        if temps[j] > temps[i]:
            res[i] = j - i
    return res

