def largest_rectangle_area(heights):
    best = 0
    for i, h in enumerate(heights):    # bar i as the shortest in its rectangle
        l = r = i
        while l > 0 and heights[l - 1] >= h:
            l -= 1
        while r + 1 < len(heights) and heights[r + 1] >= h:
            r += 1
        best = max(best, h * (r - l + 1))
    return best
